
-- Batch 1: Africa missing recipes
INSERT INTO public.recipes (name, slug, country, continent, category, difficulty, prep_time, cook_time, servings, summary, history, ingredients, steps, tags, image_url, is_african) VALUES
('Groundnut Stew', 'groundnut-stew-ghana', 'Ghana', 'Africa', 'Main Course', 'Medium', 30, 50, 6, 'A rich and creamy peanut-based stew with chicken, tomatoes, and spices, served over rice or fufu.', 'Groundnut stew is a staple across West Africa, with roots in Ghanaian and Malian cuisine. The dish reflects the region''s abundance of groundnuts (peanuts) and their central role in cooking traditions dating back centuries.', '["1 cup smooth peanut butter","1 lb chicken thighs, cubed","2 large tomatoes, blended","1 large onion, diced","3 cloves garlic, minced","1 inch ginger, grated","2 cups chicken stock","1 scotch bonnet pepper","2 tbsp palm oil","Salt and pepper to taste"]'::jsonb, '["Season chicken with salt and pepper, brown in palm oil for 5 minutes","Remove chicken, sauté onions, garlic, and ginger until fragrant","Add blended tomatoes and cook for 10 minutes until reduced","Stir in peanut butter and chicken stock, mix until smooth","Return chicken to pot, add scotch bonnet pepper whole","Simmer on low heat for 35-40 minutes until chicken is tender","Adjust seasoning and serve over rice or fufu"]'::jsonb, ARRAY['West African','Ghanaian','Stew','Peanut','Comfort Food'], 'https://images.unsplash.com/photo-1604329760661-e71dc83f8f26?w=800', true),

('Chermoula', 'chermoula-morocco', 'Morocco', 'Africa', 'Sauce', 'Easy', 15, 0, 6, 'A vibrant North African herb and spice paste used as a marinade for fish, meat, and vegetables.', 'Chermoula is an ancient Moroccan condiment that has been used for centuries along the North African coast. It combines Mediterranean herbs with African spices, reflecting the region''s position at the crossroads of culinary traditions.', '["1 cup fresh cilantro, chopped","1 cup fresh parsley, chopped","4 cloves garlic, minced","2 tsp ground cumin","1 tsp paprika","1/2 tsp cayenne pepper","Juice of 2 lemons","1/3 cup olive oil","1 tsp salt","1 preserved lemon, chopped (optional)"]'::jsonb, '["Combine cilantro, parsley, and garlic in a food processor","Add cumin, paprika, cayenne, and salt","Pulse while drizzling in olive oil and lemon juice","Blend until a thick paste forms","Add preserved lemon if using and pulse briefly","Use immediately as a marinade or store refrigerated for up to 1 week"]'::jsonb, ARRAY['Moroccan','North African','Sauce','Marinade','Herb Paste'], 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=800', true),

('Pepe Soup', 'pepe-soup-nigeria', 'Nigeria', 'Africa', 'Soup', 'Medium', 20, 60, 6, 'A fiery, aromatic pepper soup made with goat meat or fish, seasoned with a special spice blend.', 'Pepper soup is one of the most popular soups across West and Central Africa. In Nigeria, it''s often served as a remedy for colds and hangovers, and is a staple at celebrations and late-night gatherings.', '["2 lbs goat meat, cut into pieces","2 tbsp pepper soup spice mix","2 scotch bonnet peppers, crushed","1 large onion, roughly chopped","3 cloves garlic, minced","1 inch ginger, grated","2 seasoning cubes","6 cups water","Fresh scent leaves or basil","Salt to taste"]'::jsonb, '["Wash goat meat thoroughly and place in a large pot","Add onion, garlic, ginger, seasoning cubes, and water","Bring to a boil and cook for 30 minutes until meat is tender","Add pepper soup spice and scotch bonnet peppers","Simmer for another 20 minutes to develop flavors","Season with salt to taste","Garnish with fresh scent leaves and serve hot"]'::jsonb, ARRAY['Nigerian','West African','Soup','Spicy','Traditional'], 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800', true),

('Kwanga', 'kwanga-congo', 'DR Congo', 'Africa', 'Side Dish', 'Easy', 30, 60, 8, 'Fermented cassava bread wrapped in banana leaves, a staple food of Central Africa.', 'Kwanga is a traditional Congolese staple made from fermented cassava. The fermentation process gives it a distinctive sour flavor and makes the cassava safe to eat. It has been a dietary cornerstone in the Congo Basin for generations.', '["4 cups cassava flour (fermented)","3 cups water","Banana leaves for wrapping","Twine for tying","Pinch of salt"]'::jsonb, '["Mix fermented cassava flour with water to form a thick paste","Knead the dough until smooth and pliable","Divide into portions and shape into cylinders","Wrap each portion tightly in banana leaves","Tie with twine to secure","Steam or boil for 45-60 minutes until firm","Unwrap and serve alongside soups and stews"]'::jsonb, ARRAY['Congolese','Central African','Staple','Cassava','Fermented'], 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800', true),

('Pap', 'pap-south-africa', 'South Africa', 'Africa', 'Side Dish', 'Easy', 5, 20, 6, 'A smooth maize porridge that is the cornerstone of Southern African cuisine, served with meat and vegetables.', 'Pap (also known as mieliepap) is the South African version of maize porridge found throughout Southern Africa. It has been a dietary staple since maize was introduced to Africa in the 16th century, becoming central to Zulu, Xhosa, and Tswana food culture.', '["2 cups maize meal (mealie meal)","4 cups water","1 tsp salt","1 tbsp butter (optional)"]'::jsonb, '["Bring 3 cups of water to a boil in a heavy-bottomed pot","Mix maize meal with 1 cup cold water to form a slurry","Slowly pour slurry into boiling water, stirring constantly","Reduce heat to low and cover","Cook for 15-20 minutes, stirring occasionally","Add salt and butter if desired","Serve alongside braai meat, chakalaka, or stew"]'::jsonb, ARRAY['South African','Southern African','Staple','Maize','Side Dish'], 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800', true),

('Sadza', 'sadza-zimbabwe', 'Zimbabwe', 'Africa', 'Side Dish', 'Easy', 5, 25, 4, 'Zimbabwe''s staple food, a thick maize porridge eaten with relishes, stews, and vegetables.', 'Sadza is the national dish of Zimbabwe and the most important staple food. Every Zimbabwean family eats sadza almost daily, typically with a relish of meat or vegetables. The communal eating of sadza represents family unity and togetherness.', '["2 cups white maize meal","4 cups water","Pinch of salt"]'::jsonb, '["Bring 3 cups of water to a boil","Mix maize meal with 1 cup cold water","Pour mixture into boiling water while stirring","Stir vigorously to prevent lumps","Gradually add more maize meal to thicken","Cook on low heat for 20 minutes, stirring occasionally","The sadza is ready when it pulls away from the pot sides cleanly"]'::jsonb, ARRAY['Zimbabwean','Southern African','Staple','Maize','Traditional'], 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800', true),

('Sambusa', 'sambusa-somalia', 'Somalia', 'Africa', 'Appetizer', 'Medium', 30, 20, 12, 'Crispy triangular pastries filled with spiced meat or vegetables, a beloved Somali snack.', 'Sambusa arrived in East Africa through trade routes with the Arab world and India. In Somalia, these crispy pastries are an essential part of Ramadan iftar meals and are enjoyed year-round as popular street food.', '["2 cups all-purpose flour","1 lb ground beef or lamb","1 onion, finely diced","2 cloves garlic, minced","1 green chili, minced","1 tsp cumin","1/2 tsp cinnamon","Fresh cilantro, chopped","Oil for frying","Salt and pepper to taste"]'::jsonb, '["Make dough with flour, water, and salt; rest for 30 minutes","Brown meat with onions, garlic, and spices until cooked through","Add cilantro and green chili, mix well and cool","Roll dough thin and cut into strips","Fold strips into triangles, filling with meat mixture","Seal edges with water paste","Deep fry in hot oil until golden brown and crispy","Drain on paper towels and serve hot"]'::jsonb, ARRAY['Somali','East African','Appetizer','Street Food','Fried'], 'https://images.unsplash.com/photo-1601050690117-94f5f6fa8bd7?w=800', true),

('Pilau', 'pilau-kenya', 'Kenya', 'Africa', 'Main Course', 'Medium', 20, 45, 6, 'Fragrant spiced rice cooked with meat, a beloved Swahili coast dish influenced by Arab and Indian traders.', 'Pilau was brought to the Swahili coast by Arab and Indian traders centuries ago. It became deeply embedded in Kenyan coastal cuisine, particularly in Mombasa, where it''s prepared for celebrations and Friday prayers.', '["2 cups basmati rice","1 lb beef, cubed","2 large onions, thinly sliced","3 cloves garlic, minced","1 tbsp pilau masala","4 cardamom pods","4 whole cloves","1 cinnamon stick","3 cups beef stock","2 tbsp cooking oil","Salt to taste"]'::jsonb, '["Wash and soak rice for 30 minutes, then drain","Heat oil and fry onions until deep golden brown","Add garlic, cardamom, cloves, and cinnamon; fry 1 minute","Add beef and brown on all sides","Add pilau masala and salt, cook for 2 minutes","Pour in beef stock, bring to a boil","Add drained rice, stir once, then cover tightly","Cook on very low heat for 20-25 minutes until rice is fluffy","Let rest 5 minutes before serving"]'::jsonb, ARRAY['Kenyan','East African','Rice','Spiced','Swahili'], 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=800', true),

('Ful Medames', 'ful-medames-egypt', 'Egypt', 'Africa', 'Breakfast', 'Easy', 10, 15, 4, 'Slow-cooked fava beans mashed with olive oil, lemon, garlic, and cumin - Egypt''s national breakfast.', 'Ful medames is one of the oldest known prepared dishes, with evidence of consumption dating back to ancient Egypt. Today it remains the quintessential Egyptian breakfast, eaten by millions daily from street carts and home kitchens alike.', '["2 cans fava beans, drained","3 tbsp olive oil","Juice of 2 lemons","3 cloves garlic, minced","1 tsp ground cumin","1/2 tsp paprika","Fresh parsley, chopped","Salt and pepper to taste","Pita bread for serving","Hard-boiled eggs (optional)"]'::jsonb, '["Heat fava beans in a pot with a splash of water","Mash some beans while leaving others whole for texture","Add garlic, cumin, and half the lemon juice","Cook for 10 minutes, stirring occasionally","Transfer to serving bowls","Drizzle with olive oil and remaining lemon juice","Sprinkle with paprika and fresh parsley","Serve with warm pita bread and optional hard-boiled eggs"]'::jsonb, ARRAY['Egyptian','North African','Breakfast','Vegetarian','Traditional'], 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800', true),

('Couscous', 'couscous-morocco', 'Morocco', 'Africa', 'Main Course', 'Easy', 15, 30, 6, 'Fluffy steamed semolina granules served with vegetables, meat, and aromatic broth - a North African staple.', 'Couscous is the crown jewel of North African cuisine, with UNESCO recognizing it as Intangible Cultural Heritage. In Morocco, Friday couscous is a sacred family tradition, served after mosque prayers with seven vegetables.', '["2 cups couscous","2 cups boiling water or broth","2 tbsp olive oil","1 tbsp butter","1 tsp salt","1 cinnamon stick","Roasted vegetables (carrots, zucchini, chickpeas)","Fresh mint for garnish"]'::jsonb, '["Place couscous in a large bowl with salt","Pour boiling water or broth over couscous","Cover tightly and let steam for 5 minutes","Fluff with a fork, breaking up any clumps","Add olive oil and butter, fluff again","Prepare roasted vegetables with spices separately","Mound couscous on a platter, arrange vegetables on top","Garnish with fresh mint and serve with broth on the side"]'::jsonb, ARRAY['Moroccan','North African','Staple','Grain','UNESCO Heritage'], 'https://images.unsplash.com/photo-1541518763669-27fef04b14ea?w=800', true);
